pub struct NetRetry {
    pub max: u32,
    pub base_ms: u64,
}

impl NetRetry {
    pub fn backoff(&self, attempt: u32) -> u64 {
        self.base_ms << attempt.min(self.max)
    }
}

#[derive(Deserialize)]
pub struct RawConfig {
    pub http_retry: NetRetry,
}

pub fn retry_of(cfg: &RawConfig) -> &NetRetry {
