class Uploader {
    static final int MAX_RETRIES = 5;

    boolean push(Blob blob) {
        int maxAttempts = MAX_RETRIES;
        int attempt = 0;
        boolean ok = false;
        while (attempt < maxAttempts && !ok) {
            ok = tryPush(blob, attempt++);
        }
        return ok;
    }
}

