#define READ_FRAME(fd, dst) pull_frame((fd), (dst))

static char spare[64];

static int drain(int fd, char *buf, char *tail) {
    int n = pull_frame(fd, buf);
    int m = pull_frame(fd, tail);
    return n + m + READ_FRAME(fd, spare);
}

class RetryPolicy {
    public int BackoffDelay { get; set; }

    public int TotalWait(int rounds) {
        int total = 0;
        for (int i = 0; i < rounds; i++) {
            total += BackoffDelay;
        }
        return total;
    }

    public RetryPolicy(int retryDelay) {
        BackoffDelay = retryDelay;
    }
}

