static int drain(int sock_fd) {
    int n = read_frame(sock_fd, buf, MAX_LEN);
    int m = read_frame(sock_fd, tail, MAX_LEN);
    int p = read_frame(sock_fd, spare);
    int q = read_frame(sock_fd, scratch);
    return n + m + p + q;
}

