function poll(url) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("timeout")), 5000);
    http.get(url, (res) => {
      if (res.statusCode !== 200) reject(new Error("bad status"));
      else resolve(res);
    });
    socket.on("error", () => reject());
    socket.on("close", () => reject());
  });
}

