func sync(addr string) error {
	c, err := dial(addr)
	if err != nil {
		return fmt.Errorf("dial: %w", err)
	}
	data, err := c.read()
	if err != nil {
		return fmt.Errorf("read: %w", err)
	}
	if err := verify(data); err != nil {
		return err
	}
	if err := persist(data); err != nil {
		return err
	}
	return nil
}

